-- Núcleo LF S3: 21 candidatas checkout (19 legadas parcialmente cubiertas).
-- Sin emitir juicios, sin publicar, sin modificar IG, lectores, tabla puente ni legadas.
BEGIN;
DO $pre$ BEGIN
 IF (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>76
 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>0
 OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
 OR (SELECT count(*) FROM lf_ops.reglas) NOT IN (215,586)
 THEN RAISE EXCEPTION 'S3_BASELINE_DRIFT'; END IF;
END $pre$;
DO $s3$
