"s3c19_intento":false,"s3c19_contexto":false,"s3c19_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c19_intento":false,"s3c19_contexto":false,"s3c19_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c19_intento":false,"s3c19_contexto":true,"s3c19_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c19_intento":false,"s3c19_contexto":true,"s3c19_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c19_intento":true,"s3c19_contexto":false,"s3c19_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c19_intento":true,"s3c19_contexto":false,"s3c19_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c19_intento":true,"s3c19_contexto":true,"s3c19_violacion":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s3c19_intento":true,"s3c19_contexto":true,"s3c19_violacion":true},"esperado":true}]},{"tipo":"NUEVA","codigo":"S3-C20","clave":"s3_postpay_per_debt","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Ejecutar efectos postpago por deuda y modalidad con aislamiento","descripcion":"Solo PAYMENT_CONFIRMED permite efectos de backend por cada oferta/deuda independiente. Pago único que satisface total acordado habilita elegibilidad de Carta de No Adeudo; cuota inicial activa plan y registra pago del día pero no liquida deuda ni habilita carta. Una selección mixta puede tener deuda liquidada y otra en cuotas; checkout no modifica onboarding_completed.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s3c20_intento"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s3c20_contexto"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s3c20_violacion"},"der":{"lit":true}}},"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/524","solicitante":"Cristhian/Claude LF S3 2026-11-23"},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c20_intento":false,"s3c20_contexto":false,"s3c20_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c20_intento":false,"s3c20_contexto":false,"s3c20_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c20_intento":false,"s3c20_contexto":true,"s3c20_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c20_intento":false,"s3c20_contexto":true,"s3c20_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c20_intento":true,"s3c20_contexto":false,"s3c20_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c20_intento":true,"s3c20_contexto":false,"s3c20_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c20_intento":true,"s3c20_contexto":true,"s3c20_violacion":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s3c20_intento":true,"s3c20_contexto":true,"s3c20_violacion":true},"esperado":true}]},{"tipo":"NUEVA","codigo":"S3-C21","clave":"s3_receipt_real_mail","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Exigir recibo al correo real y aislar correo técnico Niubiz","descripcion":"Emitir recibo de PAYMENT_CONFIRMED exclusivamente a customer_email real registrado y validado por LF, nunca a niubiz_technical_email derivado de configuración PAGOS/NIUBIZ_EMAIL_TEMPLATE y PAGOS/NIUBIZ_EMAIL_DOMAIN. Preservar separación de identidades, no usar rebote ni aceptación técnica como pago confirmado, y registrar incidencia si falta correo real.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s3c21_intento"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s3c21_contexto"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s3c21_violacion"},"der":{"lit":true}}},"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/13126","solicitante":"Cristhian/Claude LF S3 2026-11-23"},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c21_intento":false,"s3c21_contexto":false,"s3c21_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c21_intento":false,"s3c21_contexto":false,"s3c21_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c21_intento":false,"s3c21_contexto":true,"s3c21_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c21_intento":false,"s3c21_contexto":true,"s3c21_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c21_intento":true,"s3c21_contexto":false,"s3c21_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c21_intento":true,"s3c21_contexto":false,"s3c21_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s3c21_intento":true,"s3c21_contexto":true,"s3c21_violacion":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s3c21_intento":true,"s3c21_contexto":true,"s3c21_violacion":true},"esperado":true}]}]'::jsonb) LOOP
  cd:=p->>'codigo';
  result:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF result->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (result->>'bloqueantes')::int<>0
    THEN RAISE EXCEPTION 'S3_PREFLIGHT_REJECT % %',cd,result; END IF;
  result:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF result->>'resultado'<>'CANDIDATA' OR (result->>'version')::int<>1
    THEN RAISE EXCEPTION 'S3_PROPOSAL_FAILED % %',cd,result; END IF;
  IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
  OR (SELECT count(distinct entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
    THEN RAISE EXCEPTION 'S3_VECTOR_INVALID %',cd; END IF;
  hp:=lf_ops.nucleo_hash_paquete_v1(cd,1);
  IF length(hp)<>64 THEN RAISE EXCEPTION 'S3_HASH_INVALID %',cd; END IF;
  ev:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
  IF ev->>'decision'<>'BLOQUEADA'
   OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1)<>'CANDIDATA'
    THEN RAISE EXCEPTION 'S3_NOT_BLOCKED_BEFORE_JUDGEMENT % %',cd,ev; END IF;
  RAISE NOTICE 'S3_CANDIDATA % hash=%',cd,hp;
  n:=n+1;
 END LOOP;
 IF n<>21
 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>21
 OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'S3-C%')<>0
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S3-C%' AND estado='PUBLICADA')<>0
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM before_legacy
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada r) IS DISTINCT FROM before_bridge
 OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
 THEN RAISE EXCEPTION 'S3_FINAL_INVALID'; END IF;
 RAISE NOTICE 'S3_PASS candidatas=% pruebas=168 juicio=0 promocion=0 bridge_unchanged',n;
END $s3$;
COMMIT;
